import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"排序组合（ISASI）","link":"/api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/sort_and_merge_ISASI"},{"text":"MrgSort","link":"/api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/MrgSort"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/MrgSort.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/MrgSort.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),t={name:"api/SIMD-API/basic_api/memory_vector_compute/sort_and_merge_ISASI/MrgSort.md"};function c(e,s,r,i,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>MrgSort<span id="ZH-CN_TOPIC_0000001538216637"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_proposal_intf.h&quot;</code></p><p>将已经排好序的最多4条队列，合并排列成1条队列，结果按照score域由大到小排序。</p><p>MrgSort接口通常处理经过Sort32接口预处理的数据，队列结构参考<a href="Sort32.html">Sort32功能说明</a>。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">MrgSort</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">MrgSortSrcList</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">MrgSort4Info</span><span class="o">&amp;</span><span class="w"> </span><span class="n">params</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数数据类型。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th align="left">参数名称</th><th align="left">输入/输出</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left">dst</td><td align="left">输出</td><td align="left">目的操作数。<br> 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。<br> LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td align="left">src</td><td align="left">输入</td><td align="left">源操作数，4个已经排序完成的队列，类型为MrgSortSrcList结构体，定义如下：<br>template &lt;typename T&gt; struct MrgSortSrcList {<br> __aicore__ MrgSortSrcList() {}<br> __aicore__ MrgSortSrcList(const LocalTensor&lt;T&gt; src1In, const LocalTensor&lt;T&gt; src2In, const LocalTensor&lt;T&gt; src3In, const LocalTensor&lt;T&gt; src4In)<br> {<br> src1 = src1In[0];<br> src2 = src2In[0];<br> src3 = src3In[0];<br> src4 = src4In[0];<br> }<br> LocalTensor&lt;T&gt; src1;<br> LocalTensor&lt;T&gt; src2;<br> LocalTensor&lt;T&gt; src3;<br> LocalTensor&lt;T&gt; src4;<br>};<br>src1、src2、src3、src4类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。<br>LocalTensor的起始地址需要8字节对齐。</td></tr><tr><td align="left">params</td><td align="left">输入</td><td align="left">排序参数，类型为MrgSort4Info结构体。<br> MrgSort4Info参数说明请参考<a href="MrgSort.html#%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">表MrgSort4Info结构体参数定义</a>。</td></tr></tbody></table><p><strong>表3</strong> MrgSort4Info结构体参数定义</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>elementLengths</td><td>长度为4的uint16_t数组，用于存储4个源队列的长度，单位为8B。取值范围为[0, 4095]。</td></tr><tr><td>ifExhaustedSuspension</td><td>某个队列耗尽时，控制指令是否停止执行。类型为bool，默认值为false。<br>• false：某个队列耗尽时，指令不停止。<br>• true：某个队列耗尽时，指令停止。</td></tr><tr><td>validBit</td><td>控制参与计算的队列，有效值为3、7、15。<br>•取值为3（0&#39;b0011），表示前2个队列有效。<br>•取值为7（0&#39;b0111），表示前3个队列有效。<br>•取值为15（0&#39;b1111），表示前4个队列有效。</td></tr><tr><td>repeatTimes</td><td>重复迭代次数。每次迭代完成4个队列的归并排序，源操作数和目的操作数跳过4个队列总长度。取值范围：repeatTimes∈[0, 255]。<br> repeatTimes参数生效需要满足4个条件： <br>• src包含4个队列并且长度一致。<br>• 4个队列连续存储。<br>• ifExhaustedSuspension = false。<br>• validBit = 15。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>操作数支持的数据类型为：half/float。</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>不支持源操作数和目的操作数地址重叠。</li><li>dst的起始地址需要32字节对齐，src中LocalTensor的起始地址需要8字节对齐。</li><li>如果存在score[i]==score[j]并且i&gt;j，将优先选取score[j]排在前面。</li><li>每次迭代内的数据会进行排序，不同迭代间的数据不会进行排序。</li></ul><div data-filter="A3,910b,950"><ul><li>当参数repeatTimes取值为0时，该接口的行为如下： <div data-filter="A3,910b"><ul><li>针对如下型号，当参数repeatTimes取值为0时，不会执行计算操作，不会对目的操作数进行写入，该接口将被视为NOP（空操作）。 <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，该接口通过VF调用<a href="../../reg_vector_compute/reg_vector_compute.html">Reg矢量计算</a>API实现兼容，当参数repeatTimes取值为0时，不保证该接口被视为NOP（空操作）。</li></ul></div></li></ul></div><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/01_memory_vector_compute/mrg_sort">MrgSort样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 对8个已排好序的队列进行合并排序，repeatTimes = 2，数据连续存放</span>
<span class="c1">// 每个队列包含32个(score,index)的8Bytes结构</span>
<span class="c1">// 最后输出对score域的256个数完成排序后的结果</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">MrgSort4Info</span><span class="w"> </span><span class="n">params</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">elementLengths</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">elementLengths</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">elementLengths</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">elementLengths</span><span class="p">[</span><span class="mi">3</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">ifExhaustedSuspension</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">validBit</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mb">0b1111</span><span class="p">;</span>
<span class="n">params</span><span class="p">.</span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">MrgSortSrcList</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcList</span><span class="p">;</span>
<span class="n">srcList</span><span class="p">.</span><span class="n">src1</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">workLocal</span><span class="p">[</span><span class="mi">0</span><span class="p">];</span>
<span class="n">srcList</span><span class="p">.</span><span class="n">src2</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">workLocal</span><span class="p">[</span><span class="mi">64</span><span class="p">];</span><span class="w"> </span><span class="c1">// workLocal为float类型，每个队列占据256Bytes空间</span>
<span class="n">srcList</span><span class="p">.</span><span class="n">src3</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">workLocal</span><span class="p">[</span><span class="mi">128</span><span class="p">];</span>
<span class="n">srcList</span><span class="p">.</span><span class="n">src4</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">workLocal</span><span class="p">[</span><span class="mi">192</span><span class="p">];</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">MrgSort</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcList</span><span class="p">,</span><span class="w"> </span><span class="n">params</span><span class="p">);</span>
<span class="n">outQueueDst</span><span class="p">.</span><span class="n">EnQue</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">);</span>
<span class="n">outQueueDst</span><span class="p">.</span><span class="n">FreeTensor</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const g=a(t,[["render",c]]);export{m as __pageData,g as default};
